using Backend.Persistence.Domain; using Microsoft.EntityFrameworkCore;
namespace Backend.Persistence.Data;
public sealed class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options){ public DbSet<Client> Clients=>Set<Client>(); public DbSet<Workspace> Workspaces=>Set<Workspace>(); public DbSet<Assessment> Assessments=>Set<Assessment>(); public DbSet<Spec> Specs=>Set<Spec>(); public DbSet<PipelineInstance> PipelineInstances=>Set<PipelineInstance>(); public DbSet<PhaseTransition> PhaseTransitions=>Set<PhaseTransition>(); public DbSet<PerfilCredential> PerfilCredentials=>Set<PerfilCredential>(); public DbSet<SpecPublication> SpecPublications=>Set<SpecPublication>(); public DbSet<UxGateDecision> UxGateDecisions=>Set<UxGateDecision>(); public DbSet<UxMockup> UxMockups=>Set<UxMockup>(); public DbSet<DesignSystemProposal> DesignSystemProposals=>Set<DesignSystemProposal>(); protected override void OnModelCreating(ModelBuilder m){ m.Entity<Client>(e=>{e.ToTable("client");e.HasKey(x=>x.Id);e.Property(x=>x.Name).IsRequired();e.HasIndex(x=>x.Name);}); m.Entity<Workspace>(e=>{e.ToTable("workspace",t=>{t.HasCheckConstraint("CK_workspace_platform","platform IN (0,1)");t.HasCheckConstraint("CK_workspace_status","status IN (0,1)");});e.HasKey(x=>x.Id);e.Property(x=>x.TenantId).HasDefaultValue("default");e.Property(x=>x.SpecsPath).HasDefaultValue("specs/");e.Property(x=>x.AdoWorkItemType).HasDefaultValue("User Story");e.HasIndex(x=>x.Slug).IsUnique();e.HasOne(x=>x.Client).WithMany(x=>x.Workspaces).HasForeignKey(x=>x.ClientId).OnDelete(DeleteBehavior.Restrict);}); m.Entity<Assessment>(e=>{e.ToTable("assessment");e.HasKey(x=>x.Id);e.HasOne(x=>x.Workspace).WithMany(x=>x.Assessments).HasForeignKey(x=>x.WorkspaceId);e.HasOne(x=>x.Client).WithMany(x=>x.Assessments).HasForeignKey(x=>x.ClientId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.SelectedDesignSystemProposal).WithMany().HasForeignKey(x=>x.SelectedDesignSystemProposalId).OnDelete(DeleteBehavior.Restrict);}); m.Entity<Spec>(e=>{e.ToTable("spec");e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.WorkspaceId,x.Path}).IsUnique();e.HasOne(x=>x.Workspace).WithMany(x=>x.Specs).HasForeignKey(x=>x.WorkspaceId);}); m.Entity<PipelineInstance>(e=>{e.ToTable("pipeline_instance");e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.WorkspaceId,x.ExternalRef}).IsUnique();e.HasOne(x=>x.Workspace).WithMany(x=>x.PipelineInstances).HasForeignKey(x=>x.WorkspaceId);e.HasOne(x=>x.Spec).WithMany(x=>x.PipelineInstances).HasForeignKey(x=>x.SpecId).OnDelete(DeleteBehavior.Restrict);}); m.Entity<PhaseTransition>(e=>{e.ToTable("phase_transition");e.HasKey(x=>x.Id);
  // Webhook dedup key (seção 10.1/6.2): the platform's own delivery id, checked before insert so a
  // double/quadruple-fired webhook for the same logical event never produces a second row. NULL for
  // "reported" transitions (skill implementar-spec, seção 6.1) and reconciliation-sourced rows, which
  // have no delivery id - the filter keeps those out of the uniqueness constraint entirely.
  e.HasIndex(x=>new{x.PipelineInstanceId,x.DeliveryId}).IsUnique().HasFilter("DeliveryId IS NOT NULL").HasDatabaseName("IX_phase_transition_delivery_dedup");
  e.HasOne(x=>x.PipelineInstance).WithMany(x=>x.PhaseTransitions).HasForeignKey(x=>x.PipelineInstanceId);}); m.Entity<PerfilCredential>(e=>{e.ToTable("perfil_credential");e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.WorkspaceId,x.Perfil,x.Status});
  // At most one active credential per (workspace, perfil) - CredentialStatus.Active is the enum's 0
  // value. Enforced at the DB level (not just in CredentialEndpoints.Create) so two concurrent
  // registrations for the same perfil can't both leave an "active" row: SQLite serializes writers, but
  // only this constraint actually rejects the second writer instead of letting it silently overwrite
  // the invariant the endpoint relies on.
  e.HasIndex(x=>new{x.WorkspaceId,x.Perfil}).IsUnique().HasFilter("status = 0").HasDatabaseName("IX_perfil_credential_active_per_perfil");
  e.HasOne(x=>x.Workspace).WithMany(x=>x.PerfilCredentials).HasForeignKey(x=>x.WorkspaceId);}); m.Entity<SpecPublication>(e=>{e.ToTable("spec_publication");e.HasKey(x=>x.Id);
  // One publish record per (workspace, external issue/work item) - ReconciliationPollerService trusts
  // this row's mere existence as proof "Subir US" created that external ref (Security review on PR
  // #17), so it must never end up with two conflicting rows for the same ref.
  e.HasIndex(x=>new{x.WorkspaceId,x.ExternalRef}).IsUnique().HasDatabaseName("IX_spec_publication_workspace_external_ref");
  e.HasOne(x=>x.Workspace).WithMany().HasForeignKey(x=>x.WorkspaceId);
  e.HasOne<Spec>().WithMany().HasForeignKey(x=>x.SpecId).OnDelete(DeleteBehavior.Restrict);});
  m.Entity<UxGateDecision>(e=>{e.ToTable("ux_gate_decision");e.HasKey(x=>x.Id);e.HasIndex(x=>x.PipelineInstanceId).IsUnique();e.HasOne(x=>x.PipelineInstance).WithOne(x=>x.UxGateDecision).HasForeignKey<UxGateDecision>(x=>x.PipelineInstanceId);});
  m.Entity<UxMockup>(e=>{e.ToTable("ux_mockup");e.HasKey(x=>x.Id);e.HasOne(x=>x.UxGateDecision).WithMany(x=>x.Mockups).HasForeignKey(x=>x.UxGateDecisionId);});
  m.Entity<DesignSystemProposal>(e=>{e.ToTable("design_system_proposal");e.HasKey(x=>x.Id);e.HasIndex(x=>x.WorkspaceId);e.HasOne(x=>x.Workspace).WithMany().HasForeignKey(x=>x.WorkspaceId);});
  }}
